import { toast } from "ngx-sonner";

function message(err: unknown, fallback: string) {
  return err instanceof Error ? err.message : fallback;
}

/** The toasts the app shows, so the wording is the same on every page. */
export const notify = {
  success(text: string) {
    toast.success(text);
  },
  saved(label?: string) {
    toast.success(label ? `${label} saved` : "Saved");
  },
  created(label: string) {
    toast.success(`${label} created`);
  },
  deleted(label: string) {
    toast.success(`${label} deleted`);
  },
  copied(label = "Copied to clipboard") {
    toast.success(label);
  },
  error(err: unknown, fallback = "Something went wrong") {
    toast.error(message(err, fallback));
  },
};

import { toast } from "ngx-sonner";
import { describe, expect, it, vi } from "vitest";
import { notify } from "@/ui/notify";

vi.mock("ngx-sonner", () => ({ toast: { success: vi.fn(), error: vi.fn() } }));

describe("notify", () => {
  it("words a saved toast with and without a label", () => {
    notify.saved("Agent");
    expect(toast.success).toHaveBeenCalledWith("Agent saved");
    notify.saved();
    expect(toast.success).toHaveBeenCalledWith("Saved");
  });

  it("uses an Error's message, else the fallback", () => {
    notify.error(new Error("boom"));
    expect(toast.error).toHaveBeenCalledWith("boom");
    notify.error(42);
    expect(toast.error).toHaveBeenCalledWith("Something went wrong");
  });
});

import { ChangeDetectionStrategy, Component } from "@angular/core";
import { NgxSonnerToaster } from "ngx-sonner";

/** Sonner, drawn with the `app-toast` classes in styles.css. Mount once at the root. */
@Component({
  selector: "ko-toaster",
  imports: [NgxSonnerToaster],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <ngx-sonner-toaster
      theme="dark"
      position="bottom-right"
      [closeButton]="true"
      [duration]="3500"
      [offset]="20"
      [visibleToasts]="3"
      class="app-toaster"
      [toastOptions]="toastOptions"
    />
  `,
})
export class KoToaster {
  protected readonly toastOptions = {
    unstyled: true,
    classes: {
      toast: "app-toast",
      title: "app-toast__title",
      description: "app-toast__description",
      closeButton: "app-toast__close",
      success: "app-toast--success",
      error: "app-toast--error",
      warning: "app-toast--warning",
      info: "app-toast--info",
    },
  };
}
